// async def run_co() -> None:
//     print("coroutine", await co(1), await co("xyz"))                        # -> S_RESUME_0, S_RESUME_1
//     feed = Feed(100)
//     cat = Cat(1)
//     got = await feed.fetch(cat, 10)                                         # -> S_RESUME_2
//     # the coroutine copy wrote the caller's Cat
//     print("coroutine method", got, await feed.fetch(cat, "ab"), cat.lives)  # -> S_RESUME_3
::tpystd::tpy::Poll<::std::monostate> __coro_run_co::__poll__(::tpystd::coro::Waker waker) {
    while (true) switch (__state) {
    case S_INITIAL: {  // entry
        __state = S_DONE;  // until a yield sets where to resume
        __sub_0.emplace(1);
        __state = S_RESUME_0;
        continue;
    }
    case S_RESUME_0: {  // after: print("coroutine", await co(1), await co("xyz"))
        auto __r0 = ::tpy::poll_with_cancel(__sub_0, __cancel_pending, waker);
        if (__r0.is_pending()) return ::tpystd::tpy::Poll<::std::monostate>::pending();
        __await_lift_0 = std::move(__r0).value();
        __sub_0.reset();
        __sub_1.emplace("xyz");
        __state = S_RESUME_1;
        continue;
    }
    case S_RESUME_1: {  // after: print("coroutine", await co(1), await co("xyz"))
        auto __r1 = ::tpy::poll_with_cancel(__sub_1, __cancel_pending, waker);
        if (__r1.is_pending()) return ::tpystd::tpy::Poll<::std::monostate>::pending();
        __await_lift_1 = std::move(__r1).value();
        __sub_1.reset();
        std::cout << "coroutine" << " " << __await_lift_0 << " " << __await_lift_1 << "\n" << ::tpy::check_signals;
        feed.emplace(Feed(100));
        cat.emplace(Cat(1));
        __sub_2.emplace((*feed), ::tpy::Union<Cat*, Owner*>{&((*cat))}, 10);
        __state = S_RESUME_2;
        continue;
    }
    case S_RESUME_2: {  // after: got = await feed.fetch(cat, 10)
        auto __r2 = ::tpy::poll_with_cancel(__sub_2, __cancel_pending, waker);
        if (__r2.is_pending()) return ::tpystd::tpy::Poll<::std::monostate>::pending();
        got = std::move(__r2).value();
        __sub_2.reset();
        __sub_3.emplace((*feed), ::tpy::Union<Cat*, Owner*>{&((*cat))}, "ab");
        __state = S_RESUME_3;
        continue;
    }
    case S_RESUME_3: {  // after: print("coroutine method", got, await feed.fetch(cat, "ab"), cat.lives)
        auto __r3 = ::tpy::poll_with_cancel(__sub_3, __cancel_pending, waker);
        if (__r3.is_pending()) return ::tpystd::tpy::Poll<::std::monostate>::pending();
        __await_lift_2 = std::move(__r3).value();
        __sub_3.reset();
        std::cout << "coroutine method" << " " << got << " " << __await_lift_2 << " " << (*cat).lives << "\n" << ::tpy::check_signals;
        __state = S_DONE;
        return ::tpystd::tpy::Poll<::std::monostate>::ready(::std::monostate{});
    }
    case S_DONE: ::tpy::tpy_panic("poll after Ready");
    }
    __builtin_unreachable();
}


